// Example of an SLI calculation using a Micrometer Counter
public class RequestMetrics {
    private final Counter successCounter = registry.counter("requests.success");
    private final Counter totalCounter = registry.counter("requests.total");

    public double calculateAvailability() {
        double total = totalCounter.count();
        if (total == 0) return 1.0;
        return successCounter.count() / total;
    }
}
